WITH ValidStoreSales AS (SELECT *, DAY(sale_date) AS sale_date_day FROM store_sales WHERE sale_date BETWEEN '2023-07-01' AND '2025-09-01' AND revenue >= 2400 AND sale_date BETWEEN '2024-08-11' AND '2025-08-01'), store_sales_stats AS (SELECT DATE_FORMAT(sale_date, 'yyyy-MM') AS sale_month, SUM(units) AS total_units, COUNT(revenue) AS revenue_count FROM ValidStoreSales GROUP BY DATE_FORMAT(sale_date, 'yyyy-MM')) SELECT * FROM store_sales_stats WHERE total_units < 100 ORDER BY 1 ASC
